begin; select plan(29);
select has_table('public','tkid_source_origins','managed origin registry exists');
select has_table('public','tkid_origin_verifications','verification history exists');
select has_function('public','tkid_active_origin',array['text','text'],'active-origin resolver exists');
select has_column('public','tkid_events','observed_origin','normalized event preserves observed origin');
select has_column('public','tkid_event_evidence','origin_id','Evidence references origin registry');
select has_column('public','tkid_journeys','started_origin','Journey preserves starting origin');
select has_column('public','tkid_handoffs','target_origin_id','handoff references managed destination');
insert into public.tracekit_accounts(id,account_type,name) values('d5400000-0000-0000-0000-000000000001','client','Origin A'),('d5400000-0000-0000-0000-000000000011','client','Origin B');
insert into public.tracekit_organizations(id,owning_account_id,name) values('d5400000-0000-0000-0000-000000000002','d5400000-0000-0000-0000-000000000001','Org A'),('d5400000-0000-0000-0000-000000000012','d5400000-0000-0000-0000-000000000011','Org B');
insert into public.tracekit_business_contexts(id,account_id,organization_id,name) values('origin-a','d5400000-0000-0000-0000-000000000001','d5400000-0000-0000-0000-000000000002','Origin A'),('origin-b','d5400000-0000-0000-0000-000000000011','d5400000-0000-0000-0000-000000000012','Origin B');
insert into public.tkid_sources(id,account_id,organization_id,business_context_id,public_source_id,environment,status,allowed_origins) values('d5400000-0000-4000-8000-000000000003','d5400000-0000-0000-0000-000000000001','d5400000-0000-0000-0000-000000000002','origin-a','tksrc_origin12345678901','production','disabled',array['https://legacy.example']),('d5400000-0000-4000-8000-000000000013','d5400000-0000-0000-0000-000000000011','d5400000-0000-0000-0000-000000000012','origin-b','tksrc_origin98765432109','production','disabled',array['https://legacy-b.example']);
insert into public.tkid_source_origins(id,account_id,organization_id,business_context_id,source_id,canonical_origin,role) values('d5400000-0000-4000-8000-000000000004','d5400000-0000-0000-0000-000000000001','d5400000-0000-0000-0000-000000000002','origin-a','d5400000-0000-4000-8000-000000000003','https://pushthesystem.com','frontend');
select is((select lifecycle_status from public.tkid_source_origins where id='d5400000-0000-4000-8000-000000000004'),'pending','new origin defaults Pending');
select is((select verification_state from public.tkid_source_origins where id='d5400000-0000-4000-8000-000000000004'),'unissued','verification is explicit');
select throws_ok($sql$insert into public.tkid_source_origins(account_id,organization_id,business_context_id,source_id,canonical_origin) values('d5400000-0000-0000-0000-000000000001','d5400000-0000-0000-0000-000000000002','origin-a','d5400000-0000-4000-8000-000000000003','http://pushthesystem.com')$sql$,'23514',null,'HTTP production origin rejected');
select throws_ok($sql$insert into public.tkid_source_origins(account_id,organization_id,business_context_id,source_id,canonical_origin) values('d5400000-0000-0000-0000-000000000001','d5400000-0000-0000-0000-000000000002','origin-a','d5400000-0000-4000-8000-000000000003','https://*.example.com')$sql$,'23514',null,'wildcard origin rejected');
select throws_ok($sql$insert into public.tkid_source_origins(account_id,organization_id,business_context_id,source_id,canonical_origin) values('d5400000-0000-0000-0000-000000000001','d5400000-0000-0000-0000-000000000002','origin-a','d5400000-0000-4000-8000-000000000003','https://example.com/path')$sql$,'23514',null,'path origin rejected');
select throws_ok($sql$insert into public.tkid_source_origins(account_id,organization_id,business_context_id,source_id,canonical_origin) values('d5400000-0000-0000-0000-000000000001','d5400000-0000-0000-0000-000000000002','origin-a','d5400000-0000-4000-8000-000000000003','https://pushthesystem.com')$sql$,'23505',null,'duplicate within source rejected');
select throws_ok($sql$update public.tkid_source_origins set lifecycle_status='active' where id='d5400000-0000-4000-8000-000000000004'$sql$,'23514',null,'activation before verification rejected');
insert into public.tkid_origin_verifications(organization_id,source_id,origin_id,record_name,token_digest,token_hint,expires_at) values('d5400000-0000-0000-0000-000000000002','d5400000-0000-4000-8000-000000000003','d5400000-0000-4000-8000-000000000004','_tracekit.pushthesystem.com',repeat('a',64),'last8abc',now()+interval '24 hours');
select is((select state from public.tkid_origin_verifications where origin_id='d5400000-0000-4000-8000-000000000004'),'issued','verification issuance persisted');
update public.tkid_origin_verifications set state='verified',verified_at=now() where origin_id='d5400000-0000-4000-8000-000000000004';
update public.tkid_source_origins set lifecycle_status='verified',verification_state='verified',verified_at=now() where id='d5400000-0000-4000-8000-000000000004';
update public.tkid_source_origins set lifecycle_status='active' where id='d5400000-0000-4000-8000-000000000004';
select is((select lifecycle_status from public.tkid_source_origins where id='d5400000-0000-4000-8000-000000000004'),'active','verified origin activates');
select is((select count(*)::integer from public.tkid_active_origin('tksrc_origin12345678901','https://pushthesystem.com')),0,'disabled source rejects even active origin');
update public.tkid_sources set status='shadow' where id='d5400000-0000-4000-8000-000000000003';
select is((select count(*)::integer from public.tkid_active_origin('tksrc_origin12345678901','https://pushthesystem.com')),1,'shadow source and active origin authorize exact origin');
insert into public.tkid_source_origins(account_id,organization_id,business_context_id,source_id,canonical_origin,role,lifecycle_status,verification_state,verified_at) values('d5400000-0000-0000-0000-000000000001','d5400000-0000-0000-0000-000000000002','origin-a','d5400000-0000-4000-8000-000000000003','https://pushbuttonsystem.net','oto','active','verified',now());
select is((select count(*)::integer from public.tkid_source_origins where source_id='d5400000-0000-4000-8000-000000000003' and lifecycle_status='active'),2,'multiple active origins coexist');
update public.tkid_source_origins set lifecycle_status='retired',retired_at=now() where id='d5400000-0000-4000-8000-000000000004';
select is((select count(*)::integer from public.tkid_active_origin('tksrc_origin12345678901','https://pushthesystem.com')),0,'retired origin rejects new ingestion');
select is((select canonical_origin from public.tkid_source_origins where id='d5400000-0000-4000-8000-000000000004'),'https://pushthesystem.com','retirement preserves origin provenance');
update public.tkid_source_origins set lifecycle_status='active',retired_at=null,reactivated_at=now() where id='d5400000-0000-4000-8000-000000000004';
select is((select lifecycle_status from public.tkid_source_origins where id='d5400000-0000-4000-8000-000000000004'),'active','verified retired origin reactivates');
select throws_ok($sql$insert into public.tkid_origin_verifications(organization_id,source_id,origin_id,record_name,token_digest,token_hint,expires_at) values('d5400000-0000-0000-0000-000000000012','d5400000-0000-4000-8000-000000000013','d5400000-0000-4000-8000-000000000004','_tracekit.pushthesystem.com',repeat('b',64),'last8xyz',now()+interval '1 hour')$sql$,'23503',null,'cross-Organization verification fails');
select ok((select relrowsecurity from pg_class where oid='public.tkid_source_origins'::regclass),'origin registry RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.tkid_origin_verifications'::regclass),'verification registry RLS enabled');
select is((select count(*)::integer from information_schema.role_table_grants where table_schema='public' and table_name in('tkid_source_origins','tkid_origin_verifications') and grantee in('anon','authenticated')),0,'browser receives no direct grants');
select is((select count(*)::integer from public.commerce_repository_activation),0,'no Workspace repository activated');
select is((select count(*)::integer from public.commerce_sync_schedules where enabled),0,'no production schedule enabled');
select is((select count(*)::integer from public.tkid_sources where environment='production' and status in('shadow','active')),1,'only transactional fixture source active');
select * from finish(); rollback;
